def apply_custom_format(fmt, commit, data, colorizer, branch_color, tag_color):
    """Apply a git-style format string."""
    if not fmt:
        return ""
    # Build decoration string for %d.
    branch_labels, tag_labels = refs_label(commit, data)
    decor = ""
    parts = []
    if branch_labels:
        inner = []
        for lbl in branch_labels:
            if lbl.startswith("HEAD") and " -> " in lbl:
                head, branch = lbl.split(" -> ", 1)
                inner.append(
                    colorizer.wrap(f"{head} ->", "bright_cyan") + " "
                    + colorizer.wrap(branch, branch_color or "white")
                )
            elif lbl.startswith("HEAD"):
                inner.append(colorizer.wrap(lbl, "bright_cyan"))
            else:
                inner.append(colorizer.wrap(lbl, branch_color or "white"))
        parts.append("(" + ", ".join(inner) + ")")
    if tag_labels:
        parts.append("[" + ", ".join(colorizer.wrap(t, tag_color) for t in tag_labels) + "]")
    if parts:
