            dt = _dt.datetime.strptime(d, "%a %b %d %H:%M:%S %Y %z")
            return dt.strftime("%Y-%m-%d")
        except Exception:
            return d

    placeholders = {
        "n": "\\n",
        "H": colorizer.wrap(commit["id"], "bright_yellow"),
        "h": colorizer.wrap(commit["short"], "bright_yellow"),
        "P": " ".join(commit["parents_full"]),
        "p": " ".join(commit["parents_short"]),
        "d": decor.strip() if decor else "",
        "s": commit["subject"],
